let wmEl = null, wmTab = 'map', wmV = null;
function openWorld(tab) {
  closeModal(); ccSave();
  if (ccdEl) { ccdEl.remove(); ccdEl = null; } if (cmpEl) { cmpEl.remove(); cmpEl = null; } if (twrEl) { twrEl.remove(); twrEl = null; }
  if (!wmEl) { wmEl = document.createElement('div'); wmEl.className = 'cmp wm'; wmEl.setAttribute('role', 'dialog'); wmEl.setAttribute('aria-label', 'World map'); document.body.appendChild(wmEl); wmV = null; }
  wmTab = tab || 'map';
  renderWorld();
}
function closeWorld() { if (wmEl) { wmEl.remove(); wmEl = null; } removeEventListener('resize', wmResize); bthHome(); }
const wmReg = id => WM_REGIONS.find(r => r.id === id);
/* the label under a region: the tree shows how high you've climbed, everything else is still to come */
function wmSub(r) { if (r.id !== 'tree') return 'Coming soon'; const t = ccTowerTop(); return t ? `Highest floor ${t}` : 'Start climbing'; }
function renderWorld() {
  if (!wmEl) return;
  const tab = (t, txt) => `<button class="cmp-cht ${wmTab === t ? 'on' : ''}" data-wt="${t}">${txt}${t === 'tree' && ccTowerReady() ? '<i class="cmp-dot"></i>' : ''}</button>`;
  const lab = r => `<button class="wm-lab ${r.open ? 'open' : ''}" data-wr="${r.id}" style="left:${r.at[0]}%;top:${r.at[1]}%" aria-label="${esc(r.name)}: ${esc(wmSub(r))}">
      <span class="wm-ic">${wmEmblem(r.id)}${r.id === 'tree' && ccTowerReady() ? '<i class="cmp-dot"></i>' : ''}</span>
      <b>${esc(r.name)}</b><small>${esc(wmSub(r))}</small></button>`;
  const page = wmTab !== 'map' ? wmReg(wmTab) : null;
  wmEl.innerHTML = `<header class="cmp-head wm-head"><div class="inv-title"><span class="inv-badge">${icon('compass')}</span><h2 class="ts">World Map</h2></div>
      <span class="cmp-sp"></span>
      <button class="btn ghost" id="wmCamp" title="Campaign">${icon('map')}<span class="twr-bl">Campaign</span></button><button class="btn ghost" id="wmDeck" title="Deck">${CC_IC}<span class="twr-bl">Deck</span></button>
      <button class="inv-x" id="wmClose" aria-label="Close">${icon('close')}</button>
      <nav class="cmp-chtabs wm-tabs">${tab('map', `${icon('compass')}Map`)}${WM_REGIONS.map(r => tab(r.id, esc(r.name))).join('')}</nav></header>
    <section class="wm-stage ${page ? 'paged' : ''}">
      <div class="wm-view"><div class="wm-map">${WM_SVG}${WM_REGIONS.map(lab).join('')}</div></div>
      <button class="wm-arr l" data-pan="-1,0" aria-label="Scroll the map left">${icon('back')}</button><button class="wm-arr r" data-pan="1,0" aria-label="Scroll the map right">${icon('back')}</button>
      <button class="wm-arr u" data-pan="0,-1" aria-label="Scroll the map up">${icon('back')}</button><button class="wm-arr d" data-pan="0,1" aria-label="Scroll the map down">${icon('back')}</button>
      <div class="wm-zoom"><button data-zoom="-1" aria-label="Zoom out">−</button><button data-zoom="1" aria-label="Zoom in">+</button></div>
      ${page ? `<div class="wm-page" data-r="${page.id}"><div class="wm-card">
        <span class="wm-ic big">${wmEmblem(page.id)}</span>
        <small>${esc(page.kind)}</small><h3>${esc(page.name)}</h3><b class="wm-soon">Coming soon</b>
        <button class="btn ghost" data-wt="map">${icon('back')}World map</button></div></div>` : ''}
    </section>`;
  const q = s => wmEl.querySelector(s);
  q('#wmClose').onclick = closeWorld;
  q('#wmCamp').onclick = () => { closeWorld(); openCampaign(); };
  q('#wmDeck').onclick = () => { closeWorld(); openDeck(); };
  wmEl.querySelectorAll('[data-wt]').forEach(b => b.onclick = () => wmGo(b.dataset.wt));
  wmEl.querySelectorAll('[data-pan]').forEach(b => b.onclick = () => { const [x, y] = b.dataset.pan.split(',').map(Number), v = q('.wm-view'); wmMove(-x * v.clientWidth * .35, -y * v.clientHeight * .35, true); });
  wmEl.querySelectorAll('[data-zoom]').forEach(b => b.onclick = () => { const v = q('.wm-view'); wmZoom(+b.dataset.zoom > 0 ? 1.3 : 1 / 1.3, v.clientWidth / 2, v.clientHeight / 2, true); });
  wmBind();
  const t = q(`.cmp-cht[data-wt="${wmTab}"]`); if (t) t.scrollIntoView({ block: 'nearest', inline: 'center' });
  if (page) { const v = q('.wm-view'); requestAnimationFrame(() => wmFocus(page, v)); } else requestAnimationFrame(() => wmApply(false));
  removeEventListener('resize', wmResize); addEventListener('resize', wmResize);
}
/* a region tab: the tree opens the Great Tree, every other region its own (coming soon) page; Map goes back */
function wmGo(t) {
  if (t === 'tree') { closeWorld(); openTower(); return; }
  if (wmTab === 'map' && t !== 'map') wmV.back = { ...wmV };   // remember where the map was
  if (t === 'map' && wmV && wmV.back) { const b = wmV.back; wmV = { ...b, back: null }; }
  wmTab = t; renderWorld();
}
/* the view: scale s (always covering the view) and offset; labels are counter-scaled (--is) */
function wmBase(v) { return Math.max(v.clientWidth / WM_W, v.clientHeight / WM_H); }
function wmClamp(v) {
  const b = wmBase(v); wmV.z = Math.min(2.6, Math.max(1, wmV.z)); const s = b * wmV.z;
  wmV.x = Math.min(0, Math.max(v.clientWidth - WM_W * s, wmV.x)); wmV.y = Math.min(0, Math.max(v.clientHeight - WM_H * s, wmV.y));
  return s;
}
function wmApply(ease) {
  const v = wmEl && wmEl.querySelector('.wm-view'), m = v && v.querySelector('.wm-map'); if (!m) return;
  if (!wmV) { const s0 = wmBase(v); wmV = { z: 1, x: v.clientWidth / 2 - WM_TREE[0] * s0, y: v.clientHeight / 2 - WM_TREE[1] * s0 }; }
  const s = wmClamp(v), k = Math.max(.7, Math.min(1.05, Math.min(v.clientWidth, v.clientHeight * 1.6) / 1300));
  m.classList.toggle('ease', !!ease);
  m.style.transform = `translate(${wmV.x.toFixed(1)}px, ${wmV.y.toFixed(1)}px) scale(${s.toFixed(4)})`;
  m.style.setProperty('--is', (k / s).toFixed(4));
  const at = (c, on) => { const b = wmEl.querySelector(`.wm-arr.${c}`); if (b) b.classList.toggle('off', !on); };
  at('l', wmV.x < -1); at('r', wmV.x > v.clientWidth - WM_W * s + 1); at('u', wmV.y < -1); at('d', wmV.y > v.clientHeight - WM_H * s + 1);
}
function wmMove(dx, dy, ease) { if (!wmV) return; wmV.x += dx; wmV.y += dy; wmApply(ease); }
function wmZoom(f, cx, cy, ease) {
  const v = wmEl.querySelector('.wm-view'), s0 = wmBase(v) * wmV.z;
  wmV.z *= f; const s1 = wmBase(v) * Math.min(2.6, Math.max(1, wmV.z));
  wmV.x = cx - (cx - wmV.x) * s1 / s0; wmV.y = cy - (cy - wmV.y) * s1 / s0; wmApply(ease);
}
/* a region page: the map behind it zooms in on the region */
function wmFocus(r, v) {
  const b = wmBase(v), z = 2.2, s = b * z;
  wmV = { ...(wmV || {}), z, x: v.clientWidth / 2 - r.at[0] / 100 * WM_W * s, y: v.clientHeight / 2 - r.at[1] / 100 * WM_H * s };
  wmApply(true);
}
function wmResize() { if (wmEl) wmApply(false); }
/* drag to pan (a small move still counts as a tap), wheel to zoom, hover / tap a region */
function wmBind() {
  const v = wmEl.querySelector('.wm-view'); let drag = null;
  const hl = id => wmEl.querySelectorAll('.wm-rg, .wm-lab').forEach(e => e.classList.toggle('on', !!id && e.dataset.wr === id));
  v.addEventListener('pointerdown', e => { if (wmTab !== 'map' || e.button > 0) return; drag = { x: e.clientX, y: e.clientY, ox: wmV.x, oy: wmV.y, moved: false, id: e.pointerId }; });
  v.addEventListener('pointermove', e => {
    if (drag && drag.id === e.pointerId) {
      const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
      if (!drag.moved && Math.hypot(dx, dy) > 6) { drag.moved = true; v.setPointerCapture(e.pointerId); v.classList.add('grab'); hl(null); }
      if (drag.moved) { wmV.x = drag.ox + dx; wmV.y = drag.oy + dy; wmApply(false); return; }
    }
    if (e.pointerType === 'mouse') { const t = e.target.closest('[data-wr]'); hl(t && t.dataset.wr); }
  });
  const up = e => {
    if (!drag || drag.id !== e.pointerId) return;
    const moved = drag.moved; drag = null; v.classList.remove('grab');
    if (moved) return;
    const t = e.target.closest('[data-wr]'); if (t) wmGo(t.dataset.wr);
  };
  v.addEventListener('pointerup', up); v.addEventListener('pointercancel', () => { drag = null; v.classList.remove('grab'); });
  v.addEventListener('pointerleave', e => { if (e.pointerType === 'mouse' && !drag) hl(null); });
  v.addEventListener('wheel', e => { if (wmTab !== 'map') return; e.preventDefault(); const r = v.getBoundingClientRect(); wmZoom(e.deltaY < 0 ? 1.15 : 1 / 1.15, e.clientX - r.left, e.clientY - r.top, false); }, { passive: false });
  v.addEventListener('keydown', e => { const k = { ArrowLeft: [1, 0], ArrowRight: [-1, 0], ArrowUp: [0, 1], ArrowDown: [0, -1] }[e.key]; if (k && wmTab === 'map') { e.preventDefault(); wmMove(k[0] * 120, k[1] * 120, true); } });
  wmEl.querySelectorAll('.wm-lab').forEach(b => { b.onclick = e => { if (e.detail === 0) wmGo(b.dataset.wr); }; });   // keyboard Enter (pointer taps go through pointerup)
}
